use std::{fs,path::Path,collections::{BTreeMap,BTreeSet},fmt::Write};use serde_json::{Value,json};use sha2::{Digest,Sha256};
const R:&str="/tmp/zopro-poseidon-frontier";const D:&str="/home/ubuntu/src/zk-tools/zopro/docs/benchmarks/2026-10-26-poseidon-frontier";
fn read(p:impl AsRef<Path>)->Value{serde_json::from_slice(&fs::read(p).unwrap()).unwrap()}
fn save(p:impl AsRef<Path>,v:&Value){fs::write(p,serde_json::to_vec_pretty(v).unwrap()).unwrap()}
fn hash(p:impl AsRef<Path>)->String{format!("{:x}",Sha256::digest(fs::read(p).unwrap()))}
fn array(v:&Value,key:&str)->[u64;14]{serde_json::from_value(v[key].clone()).unwrap()}
fn main(){let r=Path::new(R);let d=Path::new(D);assert_eq!(read(r.join("capture/result.json"))["status"],"complete");let mut seen:BTreeSet<String>=serde_json::from_value(read(r.join("prior-proofs.json"))).unwrap();assert_eq!(seen.len(),6928);let mut inventory=BTreeMap::new();let mut cases=BTreeMap::new();let mut scopes=0;
 for job in read(r.join("capture-jobs.json")).as_array().unwrap(){let name=job["name"].as_str().unwrap();let out=Path::new(job["directory"].as_str().unwrap());let proof=out.join("0.proof");let public=out.join("0.public");assert_eq!(fs::metadata(&proof).unwrap().len(),164);assert_eq!(hash(&public),job["public_sha256"].as_str().unwrap());assert!(seen.insert(hash(&proof)));for p in [proof,public]{inventory.insert(p.display().to_string(),hash(&p));}
  let gnark=fs::read_to_string(r.join(format!("capture/verify-{name}/stdout.log"))).unwrap();assert!(gnark.contains("verified 1 distinct proofs across 1 pinned keys"));let stdout=fs::read_to_string(r.join(format!("capture/{name}/stdout.log"))).unwrap();let summary:Value=serde_json::from_str(stdout.lines().find_map(|l|l.strip_prefix("SUMMARY ")).unwrap()).unwrap();assert_eq!(summary["rounds"],1);assert_eq!(summary["priming"],3);assert_eq!(summary["workers"],job["workers"]);
  let log=fs::read_to_string(r.join(format!("capture/{name}/stderr.log"))).unwrap();let mut beginnings=BTreeMap::new();let mut records:BTreeMap<u64,Vec<Value>>=BTreeMap::new();let mut recognition=Vec::<[u64;14]>::new();
  for line in log.lines(){if let Some(text)=line.strip_prefix("POSEIDON_FRONTIER_BEGIN "){let v:Value=serde_json::from_str(text).unwrap();assert_eq!(v["workers"],job["workers"]);assert!(beginnings.insert(v["id"].as_u64().unwrap(),v).is_none());}else if let Some(text)=line.strip_prefix("POSEIDON_FRONTIER "){let v:Value=serde_json::from_str(text).unwrap();records.entry(v["id"].as_u64().unwrap()).or_default().push(v);}else if let Some(text)=line.strip_prefix("POSEIDON_SPANS "){let v:[u64;14]=serde_json::from_str(text).unwrap();if v.iter().sum::<u64>()>0{recognition.push(v);}}}
  assert_eq!(beginnings.len(),records.len());assert!(!beginnings.is_empty());let mut plans=Vec::new();let mut actual=Vec::new();
  for(id,begin)in beginnings{let rs=records.remove(&id).unwrap();let totals:Vec<_>=rs.iter().filter(|x|x["scope"]=="total").collect();assert_eq!(totals.len(),1);let total=totals[0];let mut hashes=[0u64;14];let mut four=hashes;let mut eight=hashes;let mut maximum=hashes;let mut taskcount=0;let mut tagged=0;let mut chain=0;let mut keys=BTreeSet::new();let mut epochs=BTreeSet::new();let mut owners=BTreeSet::new();let mut ordinary=[0u64;14];let mut refined=ordinary;
   for v in rs.iter().filter(|x|x["scope"]!="total"){scopes+=1;let scope=v["scope"].as_str().unwrap();assert!(["epoch","refined"].contains(&scope));let e=v["epoch"].as_u64().unwrap();let owner=v["owner"].as_u64().unwrap();assert!(e<begin["epochs"].as_u64().unwrap());assert!(keys.insert((scope.to_string(),e,owner,v["wave"].as_u64().unwrap())));if scope=="epoch"{assert!(epochs.insert(e));}else{owners.insert(owner);}
    taskcount+=v["tasks"].as_u64().unwrap();tagged+=v["tagged_tasks"].as_u64().unwrap();chain=chain.max(v["max_chain"].as_u64().unwrap());for t in 0..14{let h=v["hashes"][t].as_u64().unwrap();let f=v["full4_hashes"][t].as_u64().unwrap();let b=v["full8_hashes"][t].as_u64().unwrap();let m=v["max_abstract_frontier"][t].as_u64().unwrap();assert!(b<=f&&f<=h&&b%8==0&&f%4==0&&m<=v["tagged_tasks"].as_u64().unwrap());hashes[t]+=h;four[t]+=f;eight[t]+=b;maximum[t]=maximum[t].max(m);if scope=="epoch"{ordinary[t]+=h;}else{refined[t]+=h;}}
   }assert_eq!(epochs.len()as u64,begin["epochs"].as_u64().unwrap());assert_eq!(owners.len()as u64,begin["refined_containers"].as_u64().unwrap());assert_eq!(taskcount,total["tasks"].as_u64().unwrap());assert_eq!(tagged,total["tagged_tasks"].as_u64().unwrap());assert_eq!(chain,total["max_chain"].as_u64().unwrap());assert_eq!(hashes,array(total,"hashes"));assert_eq!(four,array(total,"full4_hashes"));assert_eq!(eight,array(total,"full8_hashes"));assert_eq!(maximum,array(total,"max_abstract_frontier"));if hashes.iter().sum::<u64>()>0{actual.push(hashes);}
   plans.push(json!({"begin":begin,"total":total,"ordinary_hashes":ordinary,"refined_hashes":refined,"records":rs}));
  }actual.sort();recognition.sort();assert_eq!(actual,recognition,"recognition totals {name}");assert_eq!(plans.len(),1,"report per-case totals only after checking single prepared plan");cases.insert(name.to_string(),json!({"shape":job["shape"],"workers":job["workers"],"plans":plans,"existing_recognition_counters_match":true}));
 }assert_eq!(cases.len(),18);assert_eq!(seen.len(),6946);assert_eq!(inventory.len(),36);save(r.join("proof-inventory.json"),&json!(inventory));
 let mut equal=true;for case in cases.values().filter(|x|x["workers"]==32){let other=&cases[&format!("{}-w16",case["shape"].as_str().unwrap())];equal&=case["plans"][0]["total"]==other["plans"][0]["total"];}
 save(r.join("analysis.json"),&json!({"cases":cases,"sdk_requests":72,"distinct_gnark_exports":18,"next_prior_count":6946,"scope_records_checked":scopes,"worker16_32_totals_identical":equal,"speedup_claimed":false,"goal_achieved":false}));
 let mut table=String::from("|Shape|Recognized t=3 hashes|Potential full4 hashes|Potential full8 hashes|Full8 coverage|Peak abstract t=3 frontier|Max chain, any width|Refined t=3 hashes|\n|---|---:|---:|---:|---:|---:|---:|---:|\n");for job in read(r.join("capture-jobs.json")).as_array().unwrap().iter().filter(|x|x["workers"]==32){let c=&cases[job["name"].as_str().unwrap()];let p=&c["plans"][0];let t=&p["total"];let h=t["hashes"][3].as_u64().unwrap();let b=t["full8_hashes"][3].as_u64().unwrap();writeln!(table,"|{}|{h}|{}|{b}|{:.2}%|{}|{}|{}|",c["shape"].as_str().unwrap(),t["full4_hashes"][3],100.*b as f64/h as f64,t["max_abstract_frontier"][3],t["max_chain"],p["refined_hashes"][3]).unwrap();}fs::write(r.join("table.md"),&table).unwrap();println!("{table}");
 let pins=read(r.join("capture-pins.json"));for(p,h)in pins.as_object().unwrap(){assert_eq!(hash(p),h.as_str().unwrap());}let manifest=read("/tmp/zopro-grouping-module/production-source-manifest.json");for(p,h)in manifest["source_files_sha256"].as_object().unwrap(){assert_eq!(hash(Path::new("/home/ubuntu/src/zk-tools/zopro").join(p)),h.as_str().unwrap());}assert_eq!(hash("/tmp/zopro-grouping-module/native/candidate-sdk"),"03e1260e89068c2bec37a2471c34e93628a9f081903e1b7eee9cab9c306aaf3d");
 let audit=json!({"status":"verified structural census complete; larger ordinary epochs offer across-hash lane potential","sdk_requests":72,"independent_gnark_exports":18,"proof_public_members":36,"next_prior_count":6946,"prepared_plans":18,"all_recognition_counters_match":true,"scope_records_checked":scopes,"worker16_32_totals_identical":equal,"production_sources_checked_unchanged":170,"capture_pins_checked":pins.as_object().unwrap().len(),"new_core_tests":4,"native_core_tests":113,"raw_tests":2,"cubic_tests":6,"field_qualification_inherited_unchanged":true,"portable_noIFMA_consumers_pass":true,"speedup_claimed":false,"adopted":false,"goal_achieved":false,"next_action":"Prototype bounded eight-independent-width3-hash arithmetic with complete original wire/slot/A/B/C writes and scalar-prefix/dispatch costs. Use existing ordinary epoch task storage; do not batch dependent hashes or duplicate the plan. Validate realistic independent-task arrangement and fallback; the abstract regrouping model is optimistic. Primary1x2 has no full8 group here and is a negative control for that algorithm, not a required primary gain. Predeclare affected-scope gains and all-shape nonregression before performance capture; retain whole all-eight10x goal."});save(r.join("closeout.json"),&audit);
 let binary=read(r.join("native/on/artifacts.json"));let md=format!("# Poseidon independent-task census\n\nExisting ordinary solver epochs expose substantial width-three Poseidon work that could fill eight SIMD lanes in larger circuits. **Primary 1×2 has no full eight-lane group in this model**, so this mechanism alone offers no demonstrated path to its 3.7 ms target. No vector kernel or performance gain is claimed. Production is unchanged.\n\nThe private diagnostic reads the prepared schedule after existing exact Poseidon recognition. The two inserted module/call lines can be removed to recover both original files byte for byte; the other 168 originals remain unchanged. It changes no arithmetic, writes, scheduling, dependency, admission, key image or execution plan. Census state uses fixed 14-entry arrays and borrowed iterators. Source tagging guards remain active for oversized plans and unsupported tasks.\n\nEach ordinary epoch excludes refined containers. Each refined wave is analyzed separately. Within one such independent set, depth d selects the d-th recognized hash of each task after its scalar prefix, then groups equal widths. Coverage is the sum of full four/eight-lane groups at those abstract frontiers. This preserves hash order within each task. It assumes regrouping at each depth and sufficient progress through scalar prefixes; it does not measure simultaneous runtime readiness, fixed-chunk occupancy, speedup, optimal batching or a wall-time fraction.\n\n{table}\nCounts are per prepared plan, not timings. One plan is observed per process. Identical 16/32-worker totals: **{equal}**. Every width's total matches the existing independent recognition counters. All width-three hashes in these cases are in ordinary epochs; refined waves contain none. This supports investigating a bounded ordinary-epoch implementation before modifying refined execution. Other widths and tails remain in the raw records.\n\nThe four new core tests distinguish eight hashes in one dependent chain from eight independent tasks, verify mixed widths and tails, exclude refined containers, preserve wave separation, and reject malformed tags while honoring the operation-count limit. All 113 core tests, two raw tests, six cubic tests, generator and portable/no-IFMA consumer checks pass. Field code and its prior qualification are unchanged; no new field-suite run is claimed.\n\nAll nine supplied circuits are exercised at 16 and 32 workers, with CPUs 0–15 and 0–31 respectively. Each of 18 standard SDK processes runs three primes and one additional request: **72 internally verified SDK calls and 18 distinct independently Gnark-verified exports**, with 36 proof/public files. Every proof is 164 bytes, has the pinned public fixture and is fresh against 6,928 earlier identities; next ledger **6,946**. All source/library/binary/input/tool pins and 170 production hashes are checked after capture. No owned build, helper, hash or archive overlaps capture. No successful capture is repeated or excluded. The SDK is `{}`, SHA256 `{}`.\n\nNext, a component must include the original wire, slot and A/B/C writes, scalar-prefix work and dispatch costs. It must test actual task arrangement: abstract regrouping coverage can exceed what a fixed batch implementation achieves. Reusing existing epoch task storage and bounded scratch avoids another plan or a large table. Concurrent scalar tasks already use CPU threads, so packed throughput can reduce task parallelism. Those tradeoffs require measurement. A subsequent eight-lane eligibility rule naturally leaves 1×2 as a negative control; its full-proof nonregression remains required, while improvement must be demonstrated in the affected scope. No adoption follows from this census.\n\nThe [latest borrowed-G1 report](../2026-10-26-borrowed-g1/README.md) retains its experimental 8.191548 ms primary result and failed 16-worker check. The [latest full matrix](../2026-10-26-pairing-x-chain-sdk/README.md) retains all supplied M5 CPU and Metal comparisons. This census supplies no new latency comparison. The original all-eight CPU 10× goal remains active and unmet. No new AWS/Aeglos, phone, TEE, giant-circuit, minimum-RAM, swap or throughput result is claimed.\n\n[Design](artifacts/design.md), [analysis](artifacts/analysis.json), [census source](artifacts/candidate/crates/zopro-core/src/solver/sparse_poseidon/census.rs), [source audit](artifacts/source-audit.json), [capture protocol](artifacts/capture-plan.json), [proof inventory](artifacts/proof-inventory.json), [artifact hashes](artifact-index.json).\n",binary["binary"].as_str().unwrap(),binary["binary_sha256"].as_str().unwrap());fs::create_dir_all(d).unwrap();fs::write(d.join("README.md"),md).unwrap();
 fs::copy("/tmp/zopro-grouping-module/production-source-manifest.json",r.join("accepted-source-manifest.json")).unwrap();let mut index=BTreeMap::new();archive(r,r,&d.join("artifacts"),&mut index);for(p,h)in &inventory{assert_eq!(hash(d.join("artifacts").join(Path::new(p).strip_prefix(r).unwrap())),*h);}for(rel,h)in &index{assert_eq!(&hash(d.join("artifacts").join(rel)),h);}save(d.join("artifact-index.json"),&json!(index));println!("{}hashes verified;72SDK18Gnark;nextprior6946",index.len());
}
fn archive(root:&Path,here:&Path,dest:&Path,index:&mut BTreeMap<String,String>){let mut es:Vec<_>=fs::read_dir(here).unwrap().map(|e|e.unwrap().path()).collect();es.sort();for p in es{let rel=p.strip_prefix(root).unwrap();let s=rel.display().to_string();if s.starts_with("target-"){continue;}if p.is_dir(){archive(root,&p,dest,index);continue;}if s.starts_with("candidate/")&&!["candidate/crates/zopro-core/src/solver.rs","candidate/crates/zopro-core/src/solver/sparse_poseidon.rs","candidate/crates/zopro-core/src/solver/sparse_poseidon/census.rs"].contains(&s.as_str()){continue;}if !["json","jsonl","rs","md","txt","log","proof","public"].iter().any(|e|p.extension().is_some_and(|x|x==*e)){continue;}let q=dest.join(rel);fs::create_dir_all(q.parent().unwrap()).unwrap();fs::copy(&p,&q).unwrap();let h=hash(&q);assert_eq!(h,hash(&p));index.insert(s,h);}}
